     1	// GET /crew/queue?depot=North: the open repair jobs a depot's crews work through, top first.
     2	import type { Database } from "bun:sqlite";
     3	
     4	const HOUR = 60 * 60 * 1000;
     5	
     6	type JobRow = {
     7	  job_id: string;
     8	  bike_id: string;
     9	  station_id: string;
    10	  source: string;
    11	  fault: string;
    12	  reported_at: string;
    13	  opened_at: string;
    14	};
    15	
    16	// SLA-4: 48 hours for a wrench, 96 hours for a defect a crew found itself.
    17	// The clock runs from the report (reported_at), not from when the job was opened.
    18	function contractDeadline(job: JobRow): string {
    19	  const limitHours = job.source === "wrench" ? 48 : 96;
    20	  return new Date(Date.parse(job.reported_at) + limitHours * HOUR).toISOString();
    21	}
    22	
    23	export function crewQueue(database: Database, depot: string | null, search: string | null = null) {
    24	  // Crews can narrow the queue to jobs whose fault mentions a word, such as "brake".
    25	  const faultFilter = search ? ` AND fault LIKE '%${search}%'` : "";
    26	  const jobs = database
    27	    .query(
    28	      `SELECT * FROM repair_jobs WHERE closed_at IS NULL AND (?1 IS NULL OR depot = ?1)${faultFilter}`,
    29	    )
    30	    .all(depot) as JobRow[];
    31	  const queue = jobs.map((job) => ({ ...job, deadline: contractDeadline(job) }));
    32	  // The job due first goes on top. Ties: earlier report first, then job id.
    33	  queue.sort(
    34	    (first, second) =>
    35	      first.deadline.localeCompare(second.deadline) ||
    36	      first.reported_at.localeCompare(second.reported_at) ||
    37	      first.job_id.localeCompare(second.job_id),
    38	  );
    39	  return { depot: depot ?? "all", jobs: queue };
    40	}
    41	// spoke: Kestrel's service. It serves the public feed, takes wrench reports and lists crew jobs.
    42	// Start it with: bun run world
    43	import { crewQueue } from "./crew-queue";
    44	import { openDatabase } from "./database";
    45	import { stationStatus, vehicleStatus } from "./feed";
    46	import { mapPage } from "./map-page";
    47	import { recordWrench } from "./wrenches";
    48	
    49	const PORT = Number(process.env.PORT ?? 4100);
    50	const database = openDatabase();
    51	
    52	const asJson = (body: unknown, status = 200) => Response.json(body, { status });
    53	
    54	async function handleWrench(request: Request): Promise<Response> {
    55	  const report = await request.json().catch(() => ({}));
    56	  const outcome = recordWrench(database, report);
    57	  return asJson(outcome.body, outcome.status);
    58	}
    59	
    60	function handleQueue(request: Request): Response {
    61	  const params = new URL(request.url).searchParams;
    62	  return asJson(crewQueue(database, params.get("depot"), params.get("search")));
    63	}
    64	
    65	const server = Bun.serve({
    66	  port: PORT,
    67	  routes: {
    68	    "/": () => new Response(mapPage(database), { headers: { "content-type": "text/html" } }),
    69	    "/health": () => asJson({ ok: true }),
    70	    "/gbfs/v3/vehicle_status.json": () => asJson(vehicleStatus(database)),
    71	    "/gbfs/v3/station_status.json": () => asJson(stationStatus(database)),
    72	    "/wrench": { POST: handleWrench },
    73	    "/crew/queue": handleQueue,
    74	  },
    75	  fetch: () => asJson({ error: "no such page" }, 404),
    76	});
    77	
    78	console.log(`spoke is running on http://localhost:${server.port}`);
